const ic=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.help}</svg>`;
const logoMark=()=>`<svg viewBox="0 0 64 64" aria-hidden="true" class="brand-mark"><defs><linearGradient id="gf-grad" x1="0" x2="1" y1="0" y2="1"><stop offset="0%" stop-color="#8d63ef"/><stop offset="100%" stop-color="#42d9f3"/></linearGradient></defs><rect x="4" y="4" width="56" height="56" rx="18" fill="#141a2b" stroke="rgba(255,255,255,.12)"/><rect x="12" y="22" width="28" height="18" rx="6" fill="#1f263d" stroke="url(#gf-grad)" stroke-width="2"/><path d="M17 28h3M23 28h3M29 28h3M17 34h6M26 34h6" stroke="#d7dffd" stroke-width="2" stroke-linecap="round"/><circle cx="42" cy="27" r="8" fill="none" stroke="#42d9f3" stroke-width="3"/><path d="m47.5 32.5 6 6" stroke="#42d9f3" stroke-width="3" stroke-linecap="round"/><path d="M40.5 27h3" stroke="#c9b2ff" stroke-width="2" stroke-linecap="round"/></svg>`;
const storageKey='gamefinderpc-v1';
const defaults={region:'NL',currency:'EUR',view:'grid',reducedMotion:false,showSimilar:true,dense:false};
const specialLabels={free:'Бесплатные',controller:'Поддержка контроллера',earlyAccess:'Ранний доступ'};
const prettyChoiceLabel=(key,val)=>key==='tag'?tlabel(val):key==='mode'?(modeNames[val]||val):specialLabels[key]||String(val);
const tagsRu={'Survival':'Выживание','Open World':'Открытый мир','Crafting':'Крафт','Base Building':'Строительство базы','Exploration':'Исследование','Horror':'Хоррор','Co-op':'Кооператив','FPS':'Шутер от первого лица','RPG':'RPG','Story Rich':'Сюжетная','Action':'Экшен','Strategy':'Стратегия','Simulation':'Симулятор','Relaxing':'Расслабляющая','Pixel Graphics':'Пиксельная графика','Sci-fi':'Научная фантастика','Sandbox':'Песочница','Farming Sim':'Фермерство','2D':'2D','3D':'3D','Turn-Based':'Пошаговая','First-Person':'От первого лица','Third-Person':'От третьего лица','Fantasy':'Фэнтези','Zombies':'Зомби','Automation':'Автоматизация','Roguelike':'Рогалик','Roguelite':'Рогалайт','City Builder':'Градостроительство','Building':'Строительство','Free To Play':'Бесплатная','Tactical':'Тактика','Space':'Космос','Multiplayer':'Мультиплеер','Competitive':'Соревновательная','Indie':'Инди','Puzzle':'Головоломка','Platformer':'Платформер','Atmospheric':'Атмосферная','Vampires':'Вампиры','Western':'Вестерн','Underwater':'Подводный мир','Detective':'Детектив','Choices Matter':'Выборы имеют значение','Realistic':'Реализм'};
const tlabel=t=>tagsRu[t]||t;
const modeNames={'single':'Одиночная','online-coop':'Онлайн-кооператив','local-coop':'Локальный кооператив','multiplayer':'Мультиплеер','online-pvp':'Онлайн-PvP','local-pvp':'Локальное PvP','remote-play':'Remote Play Together'};
const sanitizeQuery=q=>({text:String(q?.text||'').slice(0,140),criteria:Array.isArray(q?.criteria)?q.criteria.filter(c=>c&&typeof c.key==='string'&&['required','preferred','excluded'].includes(c.priority)).slice(0,60):[],tagMatch:q?.tagMatch==='all'?'all':'any',modeMatch:q?.modeMatch==='all'?'all':'any',sort:['relevance','name','year','price-asc','price-desc','rating','reviews','storage'].includes(q?.sort)?q.sort:'relevance',includeSimilar:q?.includeSimilar!==false});
const fromStore=()=>{try{return JSON.parse(localStorage.getItem(storageKey))||{}}catch{return {}}};
const saved=fromStore();
const state={games:[],query:sanitizeQuery(DEFAULT_QUERY),favorites:new Set((saved.favorites||[]).map(Number)),favoriteNotes:saved.favoriteNotes||{},searches:saved.searches||[],settings:{...defaults,...saved.settings},quick:null,toast:[],open:new Set(['tags','modes','price']),filterFind:'',tagFind:'',tagCount:17,showFilters:false,more:{exact:12,unverified:6,similar:6},api:false,remoteCatalog:false,remoteResults:null,totalCatalog:0,remoteLoading:false,remoteError:'',remoteRequest:0,lastPath:location.pathname,lastCatalogScroll:0,pendingScroll:null};
const initURL=()=>{const params=new URLSearchParams(location.search);if(params.has('q'))state.query.text=params.get('q')||'';if(params.has('f'))try{state.query=sanitizeQuery(JSON.parse(params.get('f')))}catch{}};
initURL();
function persist(){localStorage.setItem(storageKey,JSON.stringify({favorites:[...state.favorites],favoriteNotes:state.favoriteNotes,searches:state.searches,settings:state.settings}));}
function urlQuery(){const u=new URL(location.href);if(state.query.text||state.query.criteria.length||state.query.sort!=='relevance'){u.searchParams.set('f',JSON.stringify(state.query));u.searchParams.delete('q');}else{u.searchParams.delete('f');u.searchParams.delete('q');}history.replaceState({},'',u.pathname+u.search);}
function navigate(path,options={}){const {scrollTop=true,restoreY=null}=options;if(location.pathname==='/games')state.lastCatalogScroll=window.scrollY;history.pushState({},'',path);if(path==='/games')urlQuery();state.quick=null;state.showFilters=false;state.pendingScroll=restoreY!=null?restoreY:(scrollTop?0:null);render();if(state.remoteCatalog&&/^\/games\/\d+$/.test(path))fetchGame(Number(path.split('/').pop()));if(state.remoteCatalog&&path==='/games')scheduleRemote();}
function toast(message){state.toast=[{id:Date.now(),message}];renderToasts();setTimeout(()=>{state.toast=[];renderToasts();},3000)}
function renderToasts(){let el=$('.toasts');if(!el){el=document.createElement('div');el.className='toasts';document.body.append(el)}el.innerHTML=state.toast.map(t=>`<div class="toast">${ic('check')} ${esc(t.message)}</div>`).join('')}
const getC=(key,value,op='eq')=>state.query.criteria.find(c=>c.key===key&&String(c.value)===String(value)&&c.op===op);
function setC(key,value,priority='required',op='eq'){
 state.query.criteria=state.query.criteria.filter(c=>!(c.key===key&&String(c.value)===String(value)&&c.op===op));
 if(priority)state.query.criteria.push({key,value,op,priority});
 queryChange();
}
function setNumber(key,op,raw,scale=1){const number=String(raw).trim()===''?null:Number(String(raw).replace(',','.'));state.query.criteria=state.query.criteria.filter(c=>!(c.key===key&&c.op===op));if(number!==null&&Number.isFinite(number)&&number>=0)state.query.criteria.push({key,op,value:Number((number*scale).toFixed(4)),priority:'required'});queryChange();}
function queryChange(){state.more={exact:18,unverified:18,similar:18};if(location.pathname==='/games')urlQuery();if(state.remoteCatalog){state.remoteLoading=true;state.remoteError='';scheduleRemote();}render();}
function money(g){if(g.isFree===true)return 'Бесплатно';if(g.priceCents==null)return 'Нет данных';let symbol=g.currency==='EUR'?'€':g.currency==='USD'?'$':g.currency||'€';return `${(g.priceCents/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})} ${symbol}`;}
function rating(g){if(g.reviewsPositive==null)return 'Нет данных';return `${Number(g.reviewsPositive).toFixed(0)}% положит.`;}
function storage(g){return g.storageGb==null?'Нет данных':`${Number(g.storageGb).toLocaleString('ru-RU')} ГБ`;}
function mainMode(g){return g.modes.includes('online-coop')?'Онлайн-кооператив':g.modes.includes('local-coop')?'Локальный кооп.':g.modes.includes('online-pvp')?'Онлайн-PvP':g.modes.includes('single')?'Одиночная':'Неизвестно';}
const steamUrl=g=>`https://store.steampowered.com/app/${Number(g.appId)}/`;
const coverUrl=g=>g.headerImage||`https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${Number(g.appId)}/header.jpg`;
function art(g,kind='cover') {return `<div class="${kind}" style="--art-color:${g.tags?.includes('Horror')?'#503258':'#38517c'}"><div class="cover-fallback"><span class="fallback-glyph">✦</span><b>${esc(g.name)}</b></div><img class="game-image" loading="lazy" alt="Обложка игры ${esc(g.name)}" src="${esc(coverUrl(g))}"></div>`;}
function renderHeader(){const route=location.pathname;return `<header class="topbar"><a class="brand" href="/" data-link><span class="brand-logo">${logoMark()}</span><span><b>Game<span class="brand-accent">Finder</span></b><small>PC · STEAM DISCOVERY</small></span></a><nav class="topnav" aria-label="Основная навигация"><a href="/" data-link class="${route==='/'?'active':''}">Главная</a><a href="/games" data-link class="${route.startsWith('/games')?'active':''}">Каталог игр</a><a href="/favorites" data-link class="${route==='/favorites'?'active':''}">Избранное</a><a href="/saved-searches" data-link class="${route==='/saved-searches'?'active':''}">Мои поиски</a></nav><div class="nav-end"><button class="nav-search" type="button" data-global-search aria-label="Открыть поиск игр">${ic('search')} <span>Найти игру...</span> <span class="kbd">Ctrl K</span></button><a href="/favorites" data-link class="icon-btn ${route==='/favorites'?'active':''}" aria-label="Избранное">${ic('heart')} ${state.favorites.size?`<span class="count-bubble">${state.favorites.size}</span>`:''}</a><a href="/settings" data-link class="icon-btn ${route==='/settings'?'active':''}" aria-label="Настройки">${ic('settings')}</a></div></header>`}
function renderMobileNav(){const r=location.pathname;return `<nav class="mobile-dock" aria-label="Мобильная навигация">${[['/', 'gamepad', 'Главная'],['/games','search','Каталог'],['/favorites','heart','Избранное'],['/saved-searches','bookmark','Поиски'],['/settings','settings','Настройки']].map(([url,i,name])=>`<a href="${url}" data-link class="${r===url||url==='/games'&&r.startsWith('/games')?'active':''}" aria-label="${name}">${ic(i)}<span>${name}</span></a>`).join('')}</nav>`}
function renderFooter(){return `<footer class="footer"><div>© GameFinder PC · Независимый проект, не связан с Valve или Steam.</div><div>${state.totalCatalog||state.games.length} игр в каталоге · <a href="/settings" data-link>Источники и настройки</a></div></footer>`}
function renderHome(){const heroGame=state.games.find(g=>g.appId===1091500)||state.games[0];const popular=[892970,548430,264710,1086940,739630,526870].map(id=>state.games.find(g=>g.appId===id)).filter(Boolean);return `<main class="page"><section class="hero"><div class="hero-art" style="background-image:url('${esc(coverUrl(heroGame))}')"></div><div class="hero-content"><span class="eyebrow">ПОИСК ИГР БЕЗ КОМПРОМИССОВ</span><h1>Играй в то, что <span class="gradient-text">подходит тебе.</span></h1><p>Найди следующую любимую игру в Steam. Фильтруй по жанрам, кооперативу, рейтингу, цене и десяткам других характеристик.</p><form class="hero-search" id="hero-search"><div class="search-top" style="display:flex;align-items:center;gap:10px;flex:1">${ic('search')}<input name="q" autocomplete="off" aria-label="Название игры" placeholder="Какую игру ищем?" value="${esc(state.query.text)}"></div><button class="btn btn-primary" type="submit">Найти игру ${ic('arrow')}</button></form><div class="hero-metadata"><span>${ic('grid')} ${state.totalCatalog||state.games.length} игр Steam</span><span>${ic('sliders')} Умные фильтры</span><span>${ic('check')} Без регистрации</span></div></div><div class="hero-floating" aria-hidden="true"><b>Создай идеальный запрос</b><small>Обязательно · Желательно · Исключить</small><div class="mini-bar"><i></i></div></div></section>
 <section><div class="section-head"><div><span class="eyebrow">ПОДБОРКИ ДЛЯ ТЕБЯ</span><h2>С чего начнём?</h2><p>Выбери готовое направление — фильтры применятся автоматически.</p></div><a href="/games" data-link class="btn btn-dark">Весь каталог ${ic('arrow')}</a></div><div class="preset-grid">${[
 ['friends','users','Для компании друзей','Игры с онлайн-кооперативом','#885beb'],['free','wallet','Бесплатные игры','Начни играть без покупки','#2bcda0'],['survival','sparkle','Выживание и крафт','Строй, исследуй, выживай','#e2a365'],['indie','gamepad','Небольшие открытия','Инди и необычные приключения','#40addc']
 ].map(([id,icon,title,desc,color])=>`<button class="preset" data-preset="${id}" style="--preset-color:${color}"><span class="preset-icon">${ic(icon,'icon-xl')}</span><b>${title}</b><small>${desc}</small></button>`).join('')}</div></section>
 <section><div class="section-head"><div><span class="eyebrow">ИЗ НАШЕЙ КОЛЛЕКЦИИ</span><h2>Игры, с которых стоит начать</h2><p>Разные жанры и механики — открой подробности в один клик.</p></div></div><div class="game-grid">${popular.map(g=>gameCard(g)).join('')}</div><div class="stats-row"><span>${ic('info')} Базовые теги подготовлены вручную</span><span>${ic('clock')} Цена, отзывы и размер появятся после синхронизации Steam</span></div></section>
 <section class="glass intro-card" style="margin-top:50px;display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center"><div><span class="eyebrow">ТВОИ ПРАВИЛА ИГРЫ</span><h2 style="margin-bottom:10px">Больше, чем обычный каталог.</h2><p class="tight">Добавляй обязательные условия, отмечай пожелания и исключай то, что не любишь. GameFinder честно разделяет точные, неподтверждённые и похожие результаты.</p></div><a class="btn btn-primary" href="/games" data-link>Открыть фильтры ${ic('arrow')}</a></section></main>`;}
function gameCard(g) {const tags=(g.tags||[]).slice(0,3);return `<article class="game-card" data-card="${g.appId}">${art(g)}<div class="cover-overlay">${g.isFree===true?'<span class="cover-badge free">БЕСПЛАТНО</span>':g.year>=2024?'<span class="cover-badge recent">НОВИНКА</span>':''}</div><div class="card-body"><div class="card-title-line"><a class="card-title" href="/games/${g.appId}" data-link>${esc(g.name)}</a><div class="card-actions"><button class="icon-btn ${state.favorites.has(g.appId)?'saved':''}" title="${state.favorites.has(g.appId)?'Убрать из избранного':'Добавить в избранное'}" aria-label="Избранное" data-fav="${g.appId}">${ic('heart','icon-sm')}</button><button class="icon-btn" title="Быстрый просмотр" aria-label="Быстрый просмотр" data-quick="${g.appId}">${ic('external','icon-sm')}</button></div></div><div class="chips">${tags.map(t=>`<span class="mini-chip" title="${esc(t)}">${esc(tlabel(t))}</span>`).join('')}</div><div class="card-divider"></div><div class="card-info">${info('wallet','Стоимость',money(g),g.priceCents==null&&g.isFree!==true)}${info('thumb','Отзывы Steam',rating(g),g.reviewsPositive==null)}${info('drive','Место на диске',storage(g),g.storageGb==null)}${info('users','Игровой режим',mainMode(g),!g.modes?.length)}</div><div class="card-footer"><span class="source">${g.year||'—'} · Steam AppID ${g.appId}</span><button data-quick="${g.appId}">Подробнее ${ic('arrow','icon-sm')}</button></div></div></article>`;}
function info(icon,label,value,unknown=false){return `<div class="info-line"><span class="cap">${ic(icon)} ${label}</span><strong class="${unknown?'unknown':''}">${esc(value)}</strong></div>`}
function criterionCount(group){return state.query.criteria.filter(c=>c.key===group).length}
function criterionState(key,val,op='eq'){return getC(key,val,op)?.priority||null}
function pickTag(t,key='tag'){const mode=criterionState(key,t);return `<button class="tag-choice ${mode||''}" title="${esc(mode?'Нажать, чтобы снять':'Добавить как обязательный')}" data-choice-key="${key}" data-choice-value="${esc(t)}">${esc(prettyChoiceLabel(key,t))}${mode?` ${ic(mode==='preferred'?'star':mode==='excluded'?'ban':'check','icon-sm')}`:''}</button>`}
function priorities(key,val,op='eq'){const selected=getC(key,val,op)?.priority||null;if(!selected)return '';return `<div class="selected-editor"><span>${esc(prettyChoiceLabel(key,val))}</span><div class="priority-controls" role="group" aria-label="Приоритет ${esc(prettyChoiceLabel(key,val))}">${[['required','check','Обязательно'],['preferred','star','Желательно'],['excluded','ban','Исключить']].map(([p,i,label])=>`<button class="${selected===p?'on-'+p:''}" title="${label}" aria-label="${label}" data-priority-key="${key}" data-priority-value="${esc(val)}" data-priority="${p}">${ic(i,'icon-sm')}</button>`).join('')}</div></div>`}
const groupTitles=[['tags','Жанры и теги','sparkle'],['modes','Режимы игры','users'],['price','Стоимость','wallet'],['storage','Место на диске','drive'],['reviews','Отзывы Steam','thumb'],['system','Система и железо','cpu'],['release','Дата выхода','calendar'],['extra','Дополнительно','settings']];
function groupContent(id){
 const c=state.query.criteria;const value=(key,op,scale=1)=>{const found=c.find(x=>x.key===key&&x.op===op);return found?Number(found.value)/scale:''};
 const range=(key,label,scale=1,unit='')=>`<div class="range-row"><div class="field"><label>${label} от ${unit}</label><input data-number-key="${key}" data-number-op="gte" data-number-scale="${scale}" type="number" step="${scale===100?'.01':'0.1'}" min="0" placeholder="От" value="${value(key,'gte',scale)}"></div><div class="field"><label>${label} до ${unit}</label><input data-number-key="${key}" data-number-op="lte" data-number-scale="${scale}" type="number" step="${scale===100?'.01':'0.1'}" min="0" placeholder="До" value="${value(key,'lte',scale)}"></div></div>`;
 const matchSelect=(key)=>`<div class="segment" style="margin-bottom:12px"><button class="${state.query[key+'Match']==='any'?'active':''}" data-match="${key}" data-match-value="any">Любой</button><button class="${state.query[key+'Match']==='all'?'active':''}" data-match="${key}" data-match-value="all">Все</button></div>`;
 if(id==='tags'){
  let opts=deriveTagOptions(state.games).filter(t=>!state.tagFind||`${t.tag} ${tlabel(t.tag)}`.toLowerCase().includes(state.tagFind.toLowerCase())).slice(0,state.tagCount);
  const selected=c.filter(x=>x.key==='tag');
  return `<div class="field" style="margin-bottom:10px"><label>Название тега</label><input data-tag-find placeholder="Например, строительство..." value="${esc(state.tagFind)}"></div>${matchSelect('tag')}<div class="filter-tags">${opts.map(t=>pickTag(t.tag)).join('')}</div><div style="margin-top:11px">${selected.map(x=>priorities('tag',x.value)).join('')}</div><button class="btn btn-ghost btn-small w-full" style="margin-top:10px" data-more-tags>Показать больше тегов ${ic('chevron','icon-sm')}</button><div class="priority-hint">Тег подтверждается наличием в каталоге; отсутствие тега не доказывает отсутствие механики.</div>`;
 }
 if(id==='modes')return `${matchSelect('mode')}<div class="filter-tags">${['single','online-coop','local-coop','online-pvp','multiplayer','remote-play'].map(t=>pickTag(t,'mode')).join('')}</div><div style="margin-top:10px">${c.filter(x=>x.key==='mode').map(x=>priorities('mode',x.value)).join('')}</div><div class="field" style="margin-top:12px"><label>Число участников кооператива (только подтверждённые данные)</label><input type="number" min="1" max="64" step="1" placeholder="Например, 4" data-number-key="players" data-number-op="gte" data-number-scale="1" value="${value('players','gte')}"></div><p class="range-explain">Отдельно различаем онлайн-кооператив и игру за одним компьютером.</p>`;
 if(id==='price')return `${range('price','Цена',100,'€')}<div class="range-explain" style="margin:12px 0">Регион цен: ${esc(state.settings.region)}. Неподтверждённые цены не считаются нулевыми.</div><div class="filter-tags">${pickTag('true','free')}</div>`;
 if(id==='storage')return `${range('storage','Размер',1,'ГБ')}<p class="range-explain">Заявленное место на диске, не размер скачивания.</p>`;
 if(id==='reviews')return `<div class="field"><label>Минимум положительных отзывов, %</label><input type="number" min="0" max="100" step="1" placeholder="Например, 85" data-number-key="rating" data-number-op="gte" data-number-scale="1" value="${value('rating','gte')}"></div><div class="field" style="margin-top:10px"><label>Количество отзывов от</label><input type="number" min="0" step="100" placeholder="Например, 1000" data-number-key="reviews" data-number-op="gte" data-number-scale="1" value="${value('reviews','gte')}"></div><p class="range-explain">Числа появляются только после подтверждённой синхронизации.</p>`;
 if(id==='system')return `<div class="filter-tags">${['Windows','Linux','macOS'].map(t=>pickTag(t,'os')).join('')}</div><div style="margin-top:12px">${c.filter(x=>x.key==='os').map(x=>priorities('os',x.value)).join('')}</div><div class="field" style="margin-top:12px"><label>ОЗУ до (ГБ, если сведения доступны)</label><input type="number" min="1" step="1" placeholder="Например, 8" data-number-key="ram" data-number-op="lte" data-number-scale="1" value="${value('ram','lte')}"></div>`;
 if(id==='release')return `${range('year','Год',1,'')}<p class="range-explain">Выбирай конкретный год или период релиза.</p>`;
 return `<div class="filter-tags">${pickTag('true','controller')}${pickTag('true','earlyAccess')}</div><p class="range-explain">Особые возможности зависят от полноты метаданных Steam.</p>`;
}
function renderGroup(id,title,icon){const open=state.open.has(id)||Boolean(state.filterFind&&title.toLowerCase().includes(state.filterFind.toLowerCase()));const count=state.query.criteria.filter(c=>({tags:['tag'],modes:['mode','players'],price:['price','free'],storage:['storage'],reviews:['rating','reviews'],system:['os','ram'],release:['year'],extra:['earlyAccess','controller']})[id]?.includes(c.key)).length;
 if(state.filterFind&&!title.toLowerCase().includes(state.filterFind.toLowerCase()))return '';
 return `<section class="filter-group"><button class="filter-group-header" style="width:100%;border:0;background:none;text-align:left" data-toggle-group="${id}" aria-expanded="${open}"><span class="filter-group-title">${ic(icon)}<b>${title}</b>${count?`<span class="filter-group-count">${count}</span>`:''}</span>${ic('chevron',open?'':'')}${count?`<span class="sr-only">${count} активных фильтров</span>`:''}</button>${open?`<div class="filter-group-content">${groupContent(id)}${count?`<button class="btn btn-ghost btn-small" style="margin-top:12px" data-clear-group="${id}">${ic('x','icon-sm')} Сбросить раздел</button>`:''}</div>`:''}</section>`}
function renderFilters(resultCount=0, exactCount=0){return `<aside class="filters-panel glass" id="filters-panel" aria-label="Фильтры каталога"><div class="filters-heading"><h3>${ic('sliders')} Фильтры</h3><button class="btn btn-ghost btn-small" data-clear-all>Сбросить</button></div><div class="filter-scroll" data-filter-scroll><div class="filter-find">${ic('search','icon-sm')}<input aria-label="Найти группу фильтров" placeholder="Найти фильтр..." data-filter-find value="${esc(state.filterFind)}">${state.filterFind?`<button class="icon-btn input-clear" type="button" aria-label="Очистить поиск фильтров" data-clear-text="filterFind">${ic('x','icon-sm')}</button>`:''}</div>${groupTitles.map(g=>renderGroup(...g)).join('')}</div><div class="filter-bottom"><div class="filter-summary">${state.query.criteria.length} условий · ${exactCount} точных · ${resultCount} всего</div><div class="filter-actions"><button class="btn btn-primary" data-apply-filters>${ic('search')} Показать ${resultCount} игр</button><button class="btn btn-dark filter-save-btn" data-save-search title="Сохранить текущие фильтры" aria-label="Сохранить текущий поиск">${ic('save')}<span class="sr-only">Сохранить поиск</span></button></div></div></aside>`}
function activeChips(){return state.query.criteria.map((c,i)=>`<span class="active-chip ${c.priority}" title="${c.priority==='required'?'Обязательно':c.priority==='preferred'?'Желательно':'Исключить'}">${ic(c.priority==='preferred'?'star':c.priority==='excluded'?'ban':'check','icon-sm')}${esc(criterionLabel(c))}<button aria-label="Удалить ${esc(criterionLabel(c))}" data-remove-index="${i}">${ic('x','icon-sm')}</button></span>`).join('')}
function gameTable(items){return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Игра</th><th>Режим</th><th>Цена</th><th>Отзывы</th><th>Диск</th><th>Релиз</th><th></th></tr></thead><tbody>${items.map(({game:g})=>`<tr><td><a href="/games/${g.appId}" data-link><img class="mini-cover game-image" src="${esc(coverUrl(g))}" alt="">${esc(g.name)}</a></td><td>${esc(mainMode(g))}</td><td>${esc(money(g))}</td><td>${esc(rating(g))}</td><td>${esc(storage(g))}</td><td>${g.year||'—'}</td><td><button class="icon-btn" data-quick="${g.appId}" aria-label="Открыть игру">${ic('external')}</button></td></tr>`).join('')}</tbody></table></div>`}
function renderResultGroup(group,items,label,note,style){const total=state.remoteCatalog?(state.remoteResults?.totals?.[group]??0):items.length;if(!items.length&&!total)return '';const count=state.more[group];const shown=items.slice(0,count);return `<section class="results-section"><div class="status-head ${style}"><div class="status-title"><span class="dot"></span>${label} <small>· ${total}</small></div><small>${note}</small></div>${state.settings.view==='table'?gameTable(shown):`<div class="${state.settings.view==='list'?'game-list':'game-grid '+(state.settings.dense?'dense':'')}">${shown.map(r=>gameCard(r.game)).join('')}</div>`}${shown.length<total?`<div style="text-align:center;margin-top:19px"><button class="btn btn-dark" data-more-results="${group}">Показать ещё (${total-shown.length}) ${ic('chevron')}</button></div>`:''}</section>`}
function renderCatalog(){const results=state.remoteCatalog?(state.remoteResults||{exact:[],unverified:[],similar:[],totals:{exact:0,unverified:0,similar:0}}):searchGames(state.games,state.query);const total=results.totals.exact+results.totals.unverified+(state.query.includeSimilar?results.totals.similar:0);return `<main class="page"><div class="page-head"><div><span class="eyebrow">УМНЫЙ ПОИСК STEAM</span><h1 style="font-size:clamp(30px,4vw,42px);margin:0 0 8px">Каталог игр<span style="color:var(--purple)">.</span></h1><p class="tight muted">Комбинируй любые условия — подберём то, что подходит именно тебе.</p></div><div class="notice" style="max-width:295px">${ic('info')} ${state.totalCatalog||state.games.length} игр Steam. ${state.importStatus?.status==='running'?`Импорт: ${state.importStatus.cursor.toLocaleString('ru-RU')} из ${state.importStatus.source_total.toLocaleString('ru-RU')} записей источника.`:state.importStatus?.status==='error'?'Автоимпорт временно недоступен.':'Пополнение каталога запускается через GitHub Actions.'} Характеристики части игр ещё неизвестны.</div></div><div class="catalog-shell ${state.showFilters?'show-filters':''}">${renderFilters(total,results.totals.exact)}<div class="results-area" id="results-start"><div class="results-toolbar"><div><h2>${total} <span style="color:var(--muted);font-weight:400">результатов</span></h2><div class="result-meta">${state.totalCatalog||state.games.length} игр в базе · ${results.totals.exact} точных совпадений${state.remoteLoading?' · Обновляем результаты…':''}</div></div><div class="toolbar-right"><button class="btn btn-dark btn-small mobile-filter-open" data-mobile-filter>${ic('filter')} Фильтры</button><select class="select" aria-label="Сортировка" data-sort>${[['relevance','По соответствию'],['rating','По рейтингу'],['reviews','По количеству отзывов'],['price-asc','Сначала дешевле'],['price-desc','Сначала дороже'],['year','Сначала новые'],['storage','По размеру'],['name','По названию']].map(([v,t])=>`<option value="${v}" ${state.query.sort===v?'selected':''}>${t}</option>`).join('')}</select><div class="view-switch" role="group" aria-label="Вид каталога">${[['grid','grid','Сетка'],['list','list','Список'],['table','table','Таблица']].map(([v,i,t])=>`<button title="${t}" aria-label="${t}" class="${state.settings.view===v?'active':''}" data-view="${v}">${ic(i)}</button>`).join('')}</div></div></div>${state.remoteError?`<div class="notice">${ic('info')} ${esc(state.remoteError)}</div>`:''}<div class="field" style="margin-bottom:16px"><label>Поиск по названию и тегам</label><div class="filter-find" style="margin-bottom:0;max-width:100%;padding:12px 14px">${ic('search')}<input data-catalog-search placeholder="Например, Valheim, хоррор, выживание..." style="font-size:14px" value="${esc(state.query.text)}">${state.query.text?`<button class="icon-btn input-clear" type="button" aria-label="Очистить строку поиска" data-clear-text="catalogSearch">${ic('x','icon-sm')}</button>`:''}</div></div>${state.query.criteria.length?`<div class="active-filters">${activeChips()}<button class="btn btn-ghost btn-small" data-clear-all>Очистить всё</button></div>`:''}<div style="display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap"><span class="faint">${state.query.criteria.length?'Зелёные — обязательные, фиолетовые — желательные, красные — исключения.':'Выбери фильтры слева или начни с названия игры.'}</span><label style="font-size:12px;color:#b4c0d9;display:flex;gap:8px;align-items:center"><input type="checkbox" data-similar ${state.query.includeSimilar?'checked':''}> Показывать похожие</label></div>${renderResultGroup('exact',results.exact,'Точные совпадения','Условия подтверждены','')}${renderResultGroup('unverified',results.unverified,'Требуют проверки','Недостаточно данных','unknown')}${state.query.includeSimilar?renderResultGroup('similar',results.similar,'Похожие игры','Есть известные отличия','similar'):''}${!total?`<div class="empty-state"><div class="empty-icon">${ic('search','icon-xl')}</div><h3>По таким условиям игр не найдено</h3><p>Попробуй убрать часть ограничений или проверить написание названия.</p><button class="btn btn-primary" data-clear-all>Сбросить фильтры</button></div>`:''}</div></div></main>`}
function quickMatch(game){const result=searchGames([game],state.query);return (result.exact[0]||result.unverified[0]||result.similar[0])||{group:'exact',details:[],issues:[]};}
function renderQuick(){if(!state.quick)return '';const g=state.games.find(x=>x.appId===state.quick);if(!g)return '';const m=quickMatch(g);const row=(key,val)=>`<div class="detail-row"><span class="muted">${key}</span><strong>${esc(val)}</strong></div>`;return `<div class="drawer-shade" data-shade><aside class="drawer" role="dialog" aria-modal="true" aria-label="Быстрый просмотр ${esc(g.name)}" tabindex="-1"><div class="drawer-top"><b>${ic('external')} БЫСТРЫЙ ПРОСМОТР</b><button class="icon-btn" data-close-drawer aria-label="Закрыть">${ic('x')}</button></div><div class="drawer-scroll"><div class="quick-image">${art(g,'cover')}</div><h2>${esc(g.name)}</h2><p style="font-size:13px">${esc(g.shortDescription)}</p><div class="chips">${g.tags.slice(0,6).map(t=>`<span class="mini-chip">${esc(tlabel(t))}</span>`).join('')}</div><section class="quick-section"><h3>${ic('check')} Соответствие твоему запросу</h3>${m.details.length?m.details.map(c=>{const positive=c.priority==='excluded'?c.state===false:c.state===true;const failed=c.priority==='excluded'?c.state===true:c.state===false;return `<div class="match-line ${positive?'good':failed?'failed':'unknown'}">${ic(positive?'check':failed?'x':'help','icon-sm')} <span><b>${esc(criterionLabel(c))}</b> · ${c.state===null?'Нет подтверждённых данных':positive?'Подходит':'Не соответствует'}</span></div>`}).join(''):'<p class="faint">Фильтры ещё не выбраны — добавь критерии в каталоге.</p>'}</section><section class="quick-section"><h3>Основная информация</h3>${row('Стоимость',money(g))}${row('Отзывы Steam',rating(g))}${row('Место на диске',storage(g))}${row('Режим',mainMode(g))}${row('Год выхода',String(g.year||'Неизвестно'))}${row('Разработчик',g.developers?.join(', ')||'Неизвестно')}${g.priceUpdatedAt?row('Цена обновлена',new Date(g.priceUpdatedAt).toLocaleDateString('ru-RU')):''}</section>${g.dataNote?`<p class="caption" style="margin-top:20px">${esc(g.dataNote)}</p>`:''}</div><div class="quick-bottom"><a class="btn btn-primary" href="/games/${g.appId}" data-link>Подробнее ${ic('arrow','icon-sm')}</a><a class="btn btn-dark" href="${steamUrl(g)}" target="_blank" rel="noopener noreferrer">В Steam ${ic('external','icon-sm')}</a></div></aside></div>`}
function gameDetails(){const id=Number(location.pathname.split('/').pop());const g=state.games.find(x=>x.appId===id);if(!g)return `<main class="page"><div class="empty-state"><h2>Загрузка информации об игре</h2><p>Загружаем карточку из базы каталога. Если игра отсутствует — вернись к поиску.</p><a class="btn btn-primary" href="/games" data-link>Каталог</a></div></main>`;
 const row=(title,val)=>`<div class="detail-row"><span class="muted">${title}</span><strong style="text-align:right">${esc(val)}</strong></div>`;
 const m=quickMatch(g);
 return `<main class="page"><a class="backlink" href="/games" data-link data-restore-catalog>${ic('arrow')} Назад в каталог</a><section class="detail-hero"><div class="hero-art" style="background-image:url('${esc(g.backgroundImage||coverUrl(g))}')"></div><div class="detail-hero-content"><span class="eyebrow">ИГРА В STEAM · ${g.year||'Год неизвестен'}</span><h1>${esc(g.name)}</h1><p style="color:#d7def2;max-width:650px">${esc(g.shortDescription)}</p><div class="chips">${g.tags.slice(0,6).map(t=>`<span class="mini-chip">${esc(tlabel(t))}</span>`).join('')}</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:18px"><a class="btn btn-primary" href="${steamUrl(g)}" target="_blank" rel="noopener noreferrer">Открыть в Steam ${ic('external')}</a><button class="btn btn-dark" data-fav="${g.appId}">${ic('heart')} ${state.favorites.has(g.appId)?'В избранном':'В избранное'}</button></div></div></section><div class="detail-grid"><div><section class="detail-block glass"><span class="eyebrow">ОБ ИГРЕ</span><h2 style="font-size:26px">Что это за игра?</h2><p>${esc(g.shortDescription)}</p><h3>Жанры и игровые особенности</h3><div class="chips" style="gap:8px">${g.tags.map(t=>`<span class="mini-chip" style="font-size:12px;padding:6px 9px">${esc(tlabel(t))}</span>`).join('')}</div><div class="notice" style="margin-top:18px">${ic('info')} Теги стартовой подборки отобраны вручную. Отсутствие тега не означает отсутствие механики в игре.</div></section><section class="detail-block glass"><span class="eyebrow">СИСТЕМНЫЕ ТРЕБОВАНИЯ</span><h2 style="font-size:26px">Требования к ПК</h2>${row('Место на диске',storage(g))}${row('Операционные системы',g.platforms.length?g.platforms.join(', '):'Неизвестно')}${row('Оперативная память',g.ramGb==null?'Неизвестно':g.ramGb+' ГБ')}${g.requirementsMinimum?`<h3 style="margin-top:24px">Минимальные требования</h3><p class="safe-html">${esc(String(g.requirementsMinimum).replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' '))}</p>`:''}${g.requirementsRecommended?`<h3>Рекомендуемые требования</h3><p class="safe-html">${esc(String(g.requirementsRecommended).replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' '))}</p>`:''}${!g.requirementsMinimum?'<p class="faint" style="margin-top:18px">Подробные технические требования появятся после синхронизации Steam, если источник их предоставляет.</p>':''}</section>${m.details.length?`<section class="detail-block glass"><span class="eyebrow">МОЙ ПОИСК</span><h2 style="font-size:26px">Совпадение с фильтрами</h2>${m.details.map(c=>`<div class="match-line ${c.state===null?'unknown':c.state?'good':'failed'}">${ic(c.state===null?'help':c.state?'check':'x')} <span>${esc(criterionLabel(c))} — ${c.state===null?'нет данных':c.state?'подтверждено':'не выполнено'}</span></div>`).join('')}</section>`:''}</div><aside><section class="detail-block glass"><span class="eyebrow">ХАРАКТЕРИСТИКИ</span><h3>Информация</h3>${row('Цена',money(g))}${row('Рейтинг Steam',rating(g))}${row('Количество отзывов',g.reviewsTotal==null?'Нет данных':g.reviewsTotal.toLocaleString('ru-RU'))}${row('Игровой режим',mainMode(g))}${row('Год выпуска',g.year||'Нет данных')}${row('Разработчик',g.developers.join(', ')||'Нет данных')}${row('Steam AppID',g.appId)}<a href="${steamUrl(g)}" target="_blank" rel="noopener noreferrer" class="btn btn-dark w-full" style="margin-top:17px">Страница игры Steam ${ic('external')}</a></section><section class="detail-block glass"><h3>${ic('info')} Источники данных</h3><p class="caption">Базовые AppID, названия, жанры и режимы включены в стартовую подборку. Поля, полученные из Steam, отмечаются временем обновления.</p>${row('Последнее обновление',g.updatedAt?new Date(g.updatedAt).toLocaleString('ru-RU'):'Ещё не синхронизировано')}${row('Источник',g.dataSource||'Стартовая подборка')}<div class="notice" style="margin-top:16px">${ic('info')} GameFinder — независимый проект и не является официальным сайтом Valve.</div></section></aside></div></main>`;}
function renderFavorites(){const favs=state.games.filter(g=>state.favorites.has(g.appId));return `<main class="page"><div class="page-head"><div><span class="eyebrow">ЛИЧНАЯ КОЛЛЕКЦИЯ</span><h1 style="font-size:42px">Избранные игры<span style="color:var(--purple)">.</span></h1><p>Сохраняй интересные игры и возвращайся к ним позже. Данные остаются в браузере.</p></div><a class="btn btn-dark" href="/games" data-link>${ic('plus')} Найти новые</a></div>${favs.length?`<div class="library-grid">${favs.map(g=>gameCard(g)).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">${ic('heart','icon-xl')}</div><h3>Здесь пока нет игр</h3><p>Нажми на сердечко в карточке любой игры, чтобы добавить её сюда.</p><a class="btn btn-primary" href="/games" data-link>Перейти в каталог ${ic('arrow')}</a></div>`}</main>`}
function renderSavedSearches(){return `<main class="page"><div class="page-head"><div><span class="eyebrow">ТВОИ ПОДБОРКИ</span><h1 style="font-size:42px">Мои поиски<span style="color:var(--purple)">.</span></h1><p>Сохраняй комбинации фильтров и возвращайся к ним в один клик.</p></div><button class="btn btn-primary" data-save-search>${ic('save')} Сохранить текущий</button></div>${state.searches.length?`<div class="saved-list">${state.searches.map(x=>`<article class="glass saved-card"><span class="eyebrow">СОХРАНЁННЫЙ ПОИСК</span><h3 class="tight">${esc(x.name)}</h3><div class="chips">${x.query.criteria.slice(0,5).map(c=>`<span class="mini-chip">${esc(criterionLabel(c))}</span>`).join('')}${x.query.criteria.length>5?`<span class="mini-chip">+${x.query.criteria.length-5}</span>`:''}</div><p class="caption">${x.query.criteria.length} условий · ${esc(x.created||'')}</p><div class="saved-actions"><button class="btn btn-primary btn-small" data-restore-search="${esc(x.id)}">Открыть ${ic('arrow','icon-sm')}</button><button class="btn btn-dark btn-small" data-delete-search="${esc(x.id)}">Удалить ${ic('x','icon-sm')}</button></div></article>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">${ic('bookmark','icon-xl')}</div><h3>Пока нет сохранённых поисков</h3><p>Настрой фильтры в каталоге и нажми «Сохранить поиск».</p><a class="btn btn-primary" href="/games" data-link>Открыть каталог</a></div>`}</main>`}
function renderSettings(){const s=state.settings;return `<main class="page"><div class="page-head"><div><span class="eyebrow">ПОД СЕБЯ</span><h1 style="font-size:42px">Настройки<span style="color:var(--purple)">.</span></h1><p>Управление интерфейсом, регионом Steam и локальными данными.</p></div></div><div class="settings-layout"><section class="glass settings-block"><h3>${ic('wallet')} Steam и регион</h3><p>Регион влияет на отображение цен после синхронизации Steam. Для смены региона нужно обновить сведения из источника.</p><div class="field"><label>Страна магазина</label><select data-setting="region" class="select" style="width:100%">${[['NL','Нидерланды (EUR)'],['DE','Германия (EUR)'],['FR','Франция (EUR)'],['US','США (USD)'],['GB','Великобритания (GBP)'],['PL','Польша (PLN)']].map(([v,l])=>`<option value="${v}" ${s.region===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="notice" style="margin-top:16px">${ic('info')} Изменение региона в настройках не переводит цены автоматически. При синхронизации потребуется запустить импорт с нужной страной.</div></section><section class="glass settings-block"><h3>${ic('settings')} Оформление Neon Glass</h3><p>Настрой комфорт просмотра. Тёмный режим используется как основа дизайна.</p><div class="setting-line"><label>Компактные карточки</label><button class="toggle ${s.dense?'active':''}" role="switch" aria-checked="${!!s.dense}" aria-label="Компактные карточки" data-toggle-setting="dense"></button></div><div class="setting-line"><label>Снизить анимации</label><button class="toggle ${s.reducedMotion?'active':''}" role="switch" aria-checked="${!!s.reducedMotion}" aria-label="Снизить анимации" data-toggle-setting="reducedMotion"></button></div><div class="setting-line"><label>Показывать похожие игры</label><button class="toggle ${s.showSimilar?'active':''}" role="switch" aria-checked="${!!s.showSimilar}" aria-label="Похожие игры" data-toggle-setting="showSimilar"></button></div></section><section class="glass settings-block"><h3>${ic('database'||'drive')} Локальная база</h3><p>Содержит реальные записи игр Steam. Каталог доступен даже при отсутствии подключения к Steam.</p><div class="detail-row"><span class="muted">Игр в каталоге</span><strong>${state.totalCatalog||state.games.length}</strong></div><div class="detail-row"><span class="muted">Способ доступа</span><strong>${state.api?'Локальный сервер SQLite':'Статический каталог'}</strong></div><div class="detail-row"><span class="muted">Хранение избранного</span><strong>Браузер</strong></div><div class="notice" style="margin-top:14px">${ic('info')} Для обновления карточек Steam запусти команду <code>npm run sync:steam</code> в терминале проекта.</div></section><section class="glass settings-block"><h3>${ic('save')} Резервная копия</h3><p>Экспортируй избранное, поиски и настройки. Это пригодится при смене компьютера или браузера.</p><div style="display:flex;flex-wrap:wrap;gap:10px"><button class="btn btn-dark" data-export>${ic('upload')} Экспорт JSON</button><label class="btn btn-dark" style="cursor:pointer">${ic('copy')} Импорт JSON<input type="file" accept="application/json" data-import style="display:none"></label></div><p class="caption" style="margin-top:15px">Файл содержит только твои персональные настройки и сохранённые данные.</p></section></div></main>`}
function render(){
 const path=location.pathname;
 const samePath=path===state.lastPath;
 const currentScroll=window.scrollY;
 const oldFilterScroll=$('[data-filter-scroll]')?.scrollTop ?? 0;
 const oldDrawerScroll=$('.drawer-scroll')?.scrollTop ?? 0;
 const focused=document.activeElement;
 const focusAttrs=['data-catalog-search','data-filter-find','data-tag-find','data-toggle-group','data-choice-key','data-priority-key','data-number-key','data-apply-filters'];
 const focusAttr=focusAttrs.find(a=>focused?.hasAttribute?.(a));
 const focusValues=focusAttr?Object.fromEntries([...focused.attributes].filter(a=>a.name.startsWith('data-')).map(a=>[a.name,a.value])):null;
 document.documentElement.classList.toggle('reduced-motion',Boolean(state.settings.reducedMotion));
 document.title=(path==='/games'?'Каталог игр':path==='/favorites'?'Избранное':path==='/saved-searches'?'Мои поиски':path==='/settings'?'Настройки':path.startsWith('/games/')?'Страница игры':'Найди свою следующую игру')+' — GameFinder PC';
 const page=path==='/games'?renderCatalog():path.startsWith('/games/')?gameDetails():path==='/favorites'?renderFavorites():path==='/saved-searches'?renderSavedSearches():path==='/settings'?renderSettings():renderHome();
 const partialCatalog=path==='/games'&&samePath&&Boolean($('#app main .catalog-shell'));
 if(partialCatalog){
   // Не перерисовываем шапку, страницу и каталог целиком при выборе очередного условия.
   const holder=document.createElement('div');holder.innerHTML=page;
   const shell=$('.catalog-shell');
   const fresh=holder.querySelector('.catalog-shell');
   shell.className=fresh.className;
   shell.querySelector('.filters-panel').replaceWith(fresh.querySelector('.filters-panel'));
   shell.querySelector('.results-area').replaceWith(fresh.querySelector('.results-area'));
   // Быстрый просмотр — независимый слой.
   const oldShade=$('.drawer-shade');if(oldShade)oldShade.remove();
   if(state.quick)$('#app').insertAdjacentHTML('beforeend',renderQuick());
 }else{
   $('#app').innerHTML=renderHeader()+renderMobileNav()+page+renderFooter()+(state.quick?renderQuick():'');
 }
 const filter=$('[data-filter-scroll]');
 if(filter && samePath)filter.scrollTop=oldFilterScroll;
 const drawer=$('.drawer-scroll');
 if(drawer && samePath)drawer.scrollTop=oldDrawerScroll;
 const targetScroll=state.pendingScroll!=null?state.pendingScroll:(samePath?currentScroll:0);
 state.pendingScroll=null;state.lastPath=path;
 // Восстанавливаем прокрутку синхронно, без промежуточного скачка.
 window.scrollTo({top:targetScroll,left:0,behavior:'instant'});
 if(state.quick){
   requestAnimationFrame(()=>$('.drawer [data-close-drawer]')?.focus({preventScroll:true}));
 }else if(samePath&&focusAttr){
   const matching=[...document.querySelectorAll('['+focusAttr+']')].find(el=>Object.entries(focusValues).every(([k,v])=>el.getAttribute(k)===v));
   matching?.focus({preventScroll:true});
 }
}
async function mirror(method,route,payload){if(!state.api)return;try{await fetch('/api'+route,{method,headers:{'Content-Type':'application/json'},body:payload?JSON.stringify(payload):undefined})}catch{/* browser keeps local copy */}}
function createPreset(id){state.query=sanitizeQuery(DEFAULT_QUERY);const add=(key,value,priority='required')=>state.query.criteria.push({key,value,priority,op:'eq'});
 if(id==='friends')add('mode','online-coop');
 if(id==='free')add('free',true);
 if(id==='survival'){add('tag','Survival');add('tag','Crafting','preferred');}
 if(id==='indie'){add('tag','Indie');add('tag','Exploration','preferred');}
 navigate('/games',{scrollTop:false});}
function refreshFocus(attr,position){render();const el=$(`[${attr}]`);if(el){el.focus({preventScroll:true});if(typeof position==='number'&&el.setSelectionRange)el.setSelectionRange(position,position)}}
async function onClick(ev){const btn=ev.target.closest('button,a');if(!btn)return;
 if(btn.matches('a[data-link]')){ev.preventDefault();const href=btn.getAttribute('href');if(btn.hasAttribute('data-restore-catalog')){navigate(href,{scrollTop:false,restoreY:state.lastCatalogScroll});return;}if(location.pathname==='/games'&&href?.startsWith('/games/')){state.lastCatalogScroll=window.scrollY;const id=Number(href.split('/').pop());const entry=['exact','unverified','similar'].flatMap(k=>state.remoteResults?.[k]||[]).find(x=>x.game.appId===id);if(entry&&!state.games.some(g=>g.appId===id))state.games.push(entry.game);}navigate(href);return;}
 if(btn.hasAttribute('data-global-search')){navigate('/games');requestAnimationFrame(()=>$('[data-catalog-search]')?.focus());return;}
 if(btn.hasAttribute('data-preset')){createPreset(btn.dataset.preset);return;}
 if(btn.hasAttribute('data-quick')){state.quick=Number(btn.dataset.quick);const id=state.quick;if(!state.games.some(g=>g.appId===id)){const entry=['exact','unverified','similar'].flatMap(k=>state.remoteResults?.[k]||[]).find(x=>x.game.appId===id);if(entry)state.games.push(entry.game);}render();return;}
 if(btn.hasAttribute('data-close-drawer')){state.quick=null;render();return;}
 if(btn.hasAttribute('data-fav')){const id=Number(btn.dataset.fav);if(state.favorites.has(id)){state.favorites.delete(id);mirror('DELETE','/favorites/'+id)}else{state.favorites.add(id);mirror('PUT','/favorites/'+id,{})}persist();render();toast(state.favorites.has(id)?'Игра добавлена в избранное':'Игра удалена из избранного');return;}
 if(btn.hasAttribute('data-toggle-group')){const id=btn.dataset.toggleGroup;state.open.has(id)?state.open.delete(id):state.open.add(id);render();return;}
 if(btn.hasAttribute('data-more-tags')){state.tagCount+=25;render();return;}
 if(btn.hasAttribute('data-choice-key')){const key=btn.dataset.choiceKey;const val=['free','controller','earlyAccess'].includes(key)?true:btn.dataset.choiceValue;const now=getC(key,val)?.priority;setC(key,val,now?null:'required');return;}
 if(btn.hasAttribute('data-priority-key')){setC(btn.dataset.priorityKey,btn.dataset.priorityValue,btn.dataset.priority);return;}
 if(btn.hasAttribute('data-remove-index')){state.query.criteria.splice(Number(btn.dataset.removeIndex),1);queryChange();return;}
 if(btn.hasAttribute('data-match')){state.query[btn.dataset.match+'Match']=btn.dataset.matchValue;queryChange();return;}
 if(btn.hasAttribute('data-view')){state.settings.view=btn.dataset.view;persist();render();return;}
 if(btn.hasAttribute('data-mobile-filter')){state.showFilters=!state.showFilters;render();return;}
 if(btn.hasAttribute('data-apply-filters')){const onMobile=window.matchMedia('(max-width:1080px)').matches;state.showFilters=false;render();if(onMobile)requestAnimationFrame(()=>$('#results-start')?.scrollIntoView({behavior:'smooth',block:'start'}));return;}
 if(btn.hasAttribute('data-clear-text')){if(btn.dataset.clearText==='catalogSearch')state.query.text=''; if(btn.dataset.clearText==='filterFind')state.filterFind=''; if(btn.dataset.clearText==='tagFind'){state.tagFind='';state.tagCount=17;} queryChange();return;}
 if(btn.hasAttribute('data-more-results')){const g=btn.dataset.moreResults;if(state.remoteCatalog){await loadRemoteMore(g)}else{state.more[g]+=12;render();}return;}
 if(btn.hasAttribute('data-clear-all')){state.query=sanitizeQuery(DEFAULT_QUERY);state.query.includeSimilar=state.settings.showSimilar;queryChange();toast('Фильтры сброшены');return;}
 if(btn.hasAttribute('data-clear-group')){const mapping={tags:['tag'],modes:['mode','players'],price:['price','free'],storage:['storage'],reviews:['rating','reviews'],system:['os','ram'],release:['year'],extra:['controller','earlyAccess']};state.query.criteria=state.query.criteria.filter(c=>!mapping[btn.dataset.clearGroup]?.includes(c.key));queryChange();return;}
 if(btn.hasAttribute('data-save-search')){const name=prompt('Название поискового запроса','Моя подборка');if(!name?.trim())return;const id=crypto.randomUUID();const record={id,name:name.trim().slice(0,80),created:new Date().toLocaleDateString('ru-RU'),query:JSON.parse(JSON.stringify(state.query))};state.searches.unshift(record);persist();mirror('POST','/saved-searches',{id,name:record.name,filters:record.query});render();toast('Поиск сохранён');return;}
 if(btn.hasAttribute('data-restore-search')){const record=state.searches.find(x=>x.id===btn.dataset.restoreSearch);if(record){state.query=sanitizeQuery(record.query);navigate('/games',{scrollTop:false});}return;}
 if(btn.hasAttribute('data-delete-search')){state.searches=state.searches.filter(x=>x.id!==btn.dataset.deleteSearch);persist();mirror('DELETE','/saved-searches/'+encodeURIComponent(btn.dataset.deleteSearch));render();toast('Поиск удалён');return;}
 if(btn.hasAttribute('data-toggle-setting')){const key=btn.dataset.toggleSetting;state.settings[key]=!state.settings[key];if(key==='showSimilar')state.query.includeSimilar=state.settings.showSimilar;persist();mirror('PATCH','/settings',{[key]:state.settings[key]});render();return;}
 if(btn.hasAttribute('data-export')){const payload={version:1,exportedAt:new Date().toISOString(),favorites:[...state.favorites],searches:state.searches,settings:state.settings};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='gamefinder-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия создана');return;}
}
let timer;
function onInput(ev){const el=ev.target;
 if(el.hasAttribute('data-catalog-search')) {const pos=el.selectionStart;state.query.text=el.value;clearTimeout(timer);timer=setTimeout(()=>{urlQuery();refreshFocus('data-catalog-search',pos);if(state.remoteCatalog)scheduleRemote()},230);return;}
 if(el.hasAttribute('data-filter-find')){const pos=el.selectionStart;state.filterFind=el.value;refreshFocus('data-filter-find',pos);return;}
 if(el.hasAttribute('data-tag-find')){const pos=el.selectionStart;state.tagFind=el.value;state.tagCount=50;refreshFocus('data-tag-find',pos);return;}
}
function onChange(ev){const el=ev.target;
 if(el.hasAttribute('data-number-key')){setNumber(el.dataset.numberKey,el.dataset.numberOp,el.value,Number(el.dataset.numberScale||1));return;}
 if(el.hasAttribute('data-sort')){state.query.sort=el.value;queryChange();return;}
 if(el.hasAttribute('data-similar')){state.query.includeSimilar=el.checked;queryChange();return;}
 if(el.hasAttribute('data-setting')){state.settings[el.dataset.setting]=el.value;persist();mirror('PATCH','/settings',{[el.dataset.setting]:el.value});render();toast('Настройка сохранена');return;}
 if(el.hasAttribute('data-import')){const file=el.files?.[0];if(!file)return;file.text().then(text=>{try{const data=JSON.parse(text);if(data.version!==1||!Array.isArray(data.favorites)||!Array.isArray(data.searches))throw Error('Неподдерживаемый формат');state.favorites=new Set(data.favorites.filter(Number.isInteger));state.searches=data.searches.filter(x=>x.name&&x.query);state.settings={...defaults,...data.settings};persist();render();toast('Данные восстановлены')}catch{toast('Ошибка: неверный файл резервной копии')}});return;}
}
function onSubmit(ev){if(ev.target.id==='hero-search'){ev.preventDefault();state.query.text=ev.target.elements.q.value;navigate('/games',{scrollTop:false});}}
function onKey(ev){if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();navigate('/games');requestAnimationFrame(()=>$('[data-catalog-search]')?.focus())}if(ev.key==='Escape'){if(state.quick){state.quick=null;render()}else if(state.showFilters){state.showFilters=false;render()}}}
let remoteTimer;let remoteAbort;
function scheduleRemote(){if(!state.remoteCatalog)return;clearTimeout(remoteTimer);remoteTimer=setTimeout(()=>loadRemoteResults(),180)}
async function loadRemoteResults(){
 if(!state.remoteCatalog)return;
 const ticket=++state.remoteRequest;
 remoteAbort?.abort();remoteAbort=new AbortController();
 state.remoteLoading=true;
 try{
  const url='/api/catalog?q='+encodeURIComponent(JSON.stringify(state.query));
  const response=await fetch(url,{signal:remoteAbort.signal});if(!response.ok)throw Error('HTTP '+response.status);
  const body=await response.json();if(ticket!==state.remoteRequest)return;
  state.remoteResults=body;state.remoteLoading=false;state.remoteError='';
  for(const key of ['exact','unverified','similar'])state.more[key]=18;
  render();
 }catch(e){if(e.name==='AbortError'||ticket!==state.remoteRequest)return;state.remoteLoading=false;state.remoteError='Серверный поиск временно недоступен. Последние результаты сохранены.';render();}
}
async function loadRemoteMore(group){
 if(!state.remoteResults||!['exact','unverified','similar'].includes(group))return;
 const offset=state.remoteResults[group].length;
 const url='/api/catalog?q='+encodeURIComponent(JSON.stringify(state.query))+'&group='+group+'&offset='+offset;
 const current=state.remoteRequest;
 try{const response=await fetch(url);if(!response.ok)throw Error('HTTP '+response.status);const data=await response.json();if(current!==state.remoteRequest)return;state.remoteResults[group].push(...(data[group]||[]));state.more[group]=state.remoteResults[group].length;render();}
 catch{toast('Не удалось загрузить следующую страницу игр');}
}
async function fetchGame(id){
 if(state.games.some(g=>g.appId===id))return;
 try{const res=await fetch('/api/games/'+id);if(!res.ok)return;const g=await res.json();if(!Array.isArray(g.tags))g.tags=[];if(!Array.isArray(g.modes))g.modes=[];if(!Array.isArray(g.platforms))g.platforms=[];if(!Array.isArray(g.developers))g.developers=[];state.games.push(g);if(location.pathname==='/games/'+id||location.pathname==='/favorites')render();}
 catch{};
}
async function init(){
 try{const meta=await fetch('/api/catalog/meta').then(r=>r.json());if(meta.available){state.remoteCatalog=true;state.totalCatalog=Number(meta.total)||0;state.importStatus=meta.importStatus||null;}}catch{}
 try{const res=await fetch('/api/games',{headers:{Accept:'application/json'}});if(!res.ok||!res.headers.get('content-type')?.includes('application/json'))throw Error('Static mode');const data=await res.json();if(!Array.isArray(data.games))throw Error('Invalid API');state.games=data.games;state.api=true;}
 catch{try{const r=await fetch('/data/games.json');const data=await r.json();state.games=Array.isArray(data)?data:data.games||[];}catch{state.games=[];}}
 state.totalCatalog ||= state.games.length;

 document.addEventListener('click',onClick);document.addEventListener('input',onInput);document.addEventListener('change',onChange);document.addEventListener('submit',onSubmit);document.addEventListener('keydown',onKey);window.addEventListener('popstate',()=>{initURL();if(location.pathname==='/games')state.pendingScroll=state.lastCatalogScroll;render()});
 document.addEventListener('load',ev=>{if(ev.target?.tagName==='IMG'&&ev.target.classList.contains('game-image'))ev.target.closest('.cover')?.classList.add('loaded')},true);
 document.addEventListener('error',ev=>{if(ev.target?.tagName==='IMG'&&ev.target.classList.contains('game-image'))ev.target.closest('.cover')?.classList.add('image-failed')},true);
 document.addEventListener('click',ev=>{if(ev.target.matches('.drawer-shade')){state.quick=null;render()}});
 state.query.includeSimilar=state.query.includeSimilar&&state.settings.showSimilar;
 render();if(state.remoteCatalog){await loadRemoteResults();if(/^\/games\/\d+$/.test(location.pathname))fetchGame(Number(location.pathname.split('/').pop()));if(state.favorites.size){for(const id of [...state.favorites].slice(0,100))if(!state.games.some(g=>g.appId===id))fetchGame(id);}}
}
init();
